-- ==============================================================================
-- ATELIER DIGITAL — ROLLBACK FORTALECIDO: RETIRO EXCLUSIVO DE DATOS DE DEMOSTRACIÓN
-- Archivo: supabase/demo/rollback_demo_colegio_30_alumnos.sql
-- Base de Datos: trgoqqvsprknswobvniu
-- Propósito: Retirar de forma limpia, atómica y segura el 100% de los datos del
-- escenario institucional de 30 alumnos respetando los triggers de producción.
-- 
-- PROTOCOLO DE SEGURIDAD ESTRICTO:
--   1. Verifica la existencia e identidad del cliente sintético titular.
--   2. Verifica la identidad y pertenencia del grupo escolar y la campaña.
--   3. Verifica los 30 alumnos y su relación exacta con el cliente.
--   4. Verifica los 30 miembros del grupo.
--   5. Verifica los 30 participantes de la jornada de medición.
--   6. Verifica individualmente las 30 sesiones y exige que el 100% esté en 'draft'.
--   7. Verifica los 300 valores de medición.
--   8. Verifica las 45 creaciones y sus vínculos con los alumnos.
--   9. Verifica la inexistencia de datos externos o ejecuciones dependientes.
--  10. Ejecuta la eliminación en estricto orden inverso de dependencias.
--  11. Valida que no quede ningún registro residual del demo (Cero huérfanos).
-- 
-- REGLAS INMUTABLES:
--   * NUNCA deshabilita triggers (Cero ALTER TABLE DISABLE TRIGGER).
--   * Este archivo es una propuesta de rollback: validar FKs de la BD antes de ejecutarlo.
--   * NUNCA fuerza cambios de estado ni archiva registros para simular eliminación.
--   * Si falta un registro esperado o alguna sesión no está en 'draft', ABORTA TODO.
-- ==============================================================================

BEGIN;

DO $$
DECLARE
    v_client_id UUID := 'e1a10000-0000-4000-8000-000000000001';
    v_group_id UUID := 'e1a20000-0000-4000-8000-000000000001';
    v_campaign_id UUID := 'e1a30000-0000-4000-8000-000000000001';

    v_count INT := 0;
    v_non_draft_count INT := 0;
    v_non_draft_details TEXT := '';
    v_external_ref_count INT := 0;
    v_remaining_count INT := 0;
BEGIN
    -- ==========================================================================
    -- 1. VERIFICACIÓN DE EXISTENCIA E IDENTIDAD DEL CLIENTE SINTÉTICO
    -- ==========================================================================
    SELECT COUNT(*) INTO v_count
    FROM public.clients
    WHERE id = v_client_id
      AND full_name = 'COLEGIO DEMOSTRACIÓN ATELIER - BARRANQUILLA'
      AND email = 'rectoria.demo@colegioatelier.edu.co'
;

    IF v_count <> 1 THEN
        RAISE EXCEPTION 'DETENCIÓN DE SEGURIDAD: El cliente sintético titular % no existe o sus atributos no corresponden al escenario.', v_client_id;
    END IF;

    -- ==========================================================================
    -- 2. VERIFICACIÓN DE IDENTIDAD Y PERTENENCIA DEL GRUPO Y LA CAMPAÑA
    -- ==========================================================================
    SELECT COUNT(*) INTO v_count
    FROM public.groups
    WHERE id = v_group_id
      AND client_id = v_client_id
      AND name = 'CURSO DEMOSTRACIÓN 30 ALUMNOS';

    IF v_count <> 1 THEN
        RAISE EXCEPTION 'DETENCIÓN DE SEGURIDAD: El grupo escolar % no existe o no pertenece al cliente.', v_group_id;
    END IF;

    SELECT COUNT(*) INTO v_count
    FROM public.measurement_campaigns
    WHERE id = v_campaign_id
      AND client_id = v_client_id
      AND group_id = v_group_id
      AND title = 'JORNADA DE MEDIDAS - CURSO DEMOSTRACIÓN';

    IF v_count <> 1 THEN
        RAISE EXCEPTION 'DETENCIÓN DE SEGURIDAD: La campaña de medición % no existe o no corresponde al grupo/cliente.', v_campaign_id;
    END IF;

    -- ==========================================================================
    -- 3. VERIFICACIÓN DE LOS 30 ALUMNOS (PERSONAS BENEFICIARIAS)
    -- ==========================================================================
    SELECT COUNT(*) INTO v_count
    FROM public.persons
    WHERE id IN ('e1b00000-0000-4000-8000-000000000001','e1b00000-0000-4000-8000-000000000002','e1b00000-0000-4000-8000-000000000003','e1b00000-0000-4000-8000-000000000004','e1b00000-0000-4000-8000-000000000005','e1b00000-0000-4000-8000-000000000006','e1b00000-0000-4000-8000-000000000007','e1b00000-0000-4000-8000-000000000008','e1b00000-0000-4000-8000-000000000009','e1b00000-0000-4000-8000-000000000010','e1b00000-0000-4000-8000-000000000011','e1b00000-0000-4000-8000-000000000012','e1b00000-0000-4000-8000-000000000013','e1b00000-0000-4000-8000-000000000014','e1b00000-0000-4000-8000-000000000015','e1b00000-0000-4000-8000-000000000016','e1b00000-0000-4000-8000-000000000017','e1b00000-0000-4000-8000-000000000018','e1b00000-0000-4000-8000-000000000019','e1b00000-0000-4000-8000-000000000020','e1b00000-0000-4000-8000-000000000021','e1b00000-0000-4000-8000-000000000022','e1b00000-0000-4000-8000-000000000023','e1b00000-0000-4000-8000-000000000024','e1b00000-0000-4000-8000-000000000025','e1b00000-0000-4000-8000-000000000026','e1b00000-0000-4000-8000-000000000027','e1b00000-0000-4000-8000-000000000028','e1b00000-0000-4000-8000-000000000029','e1b00000-0000-4000-8000-000000000030')
      AND client_id = v_client_id
      AND demographic_category IN ('boy','girl');

    IF v_count <> 30 THEN
        RAISE EXCEPTION 'DETENCIÓN DE SEGURIDAD: Se esperaban 30 alumnos vinculados al cliente, pero se encontraron %.', v_count;
    END IF;

    -- ==========================================================================
    -- 4. VERIFICACIÓN DE LOS 30 MIEMBROS DEL GRUPO ESCOLAR
    -- ==========================================================================
    SELECT COUNT(*) INTO v_count
    FROM public.group_members
    WHERE group_id = v_group_id
      AND person_id IN ('e1b00000-0000-4000-8000-000000000001','e1b00000-0000-4000-8000-000000000002','e1b00000-0000-4000-8000-000000000003','e1b00000-0000-4000-8000-000000000004','e1b00000-0000-4000-8000-000000000005','e1b00000-0000-4000-8000-000000000006','e1b00000-0000-4000-8000-000000000007','e1b00000-0000-4000-8000-000000000008','e1b00000-0000-4000-8000-000000000009','e1b00000-0000-4000-8000-000000000010','e1b00000-0000-4000-8000-000000000011','e1b00000-0000-4000-8000-000000000012','e1b00000-0000-4000-8000-000000000013','e1b00000-0000-4000-8000-000000000014','e1b00000-0000-4000-8000-000000000015','e1b00000-0000-4000-8000-000000000016','e1b00000-0000-4000-8000-000000000017','e1b00000-0000-4000-8000-000000000018','e1b00000-0000-4000-8000-000000000019','e1b00000-0000-4000-8000-000000000020','e1b00000-0000-4000-8000-000000000021','e1b00000-0000-4000-8000-000000000022','e1b00000-0000-4000-8000-000000000023','e1b00000-0000-4000-8000-000000000024','e1b00000-0000-4000-8000-000000000025','e1b00000-0000-4000-8000-000000000026','e1b00000-0000-4000-8000-000000000027','e1b00000-0000-4000-8000-000000000028','e1b00000-0000-4000-8000-000000000029','e1b00000-0000-4000-8000-000000000030');

    IF v_count <> 30 THEN
        RAISE EXCEPTION 'DETENCIÓN DE SEGURIDAD: Se esperaban 30 miembros en el grupo %, pero se encontraron %.', v_group_id, v_count;
    END IF;

    -- ==========================================================================
    -- 5. VERIFICACIÓN DE LOS 30 PARTICIPANTES DE LA CAMPAÑA
    -- ==========================================================================
    SELECT COUNT(*) INTO v_count
    FROM public.measurement_campaign_participants
    WHERE id IN ('e1d00000-0000-4000-8000-000000000001','e1d00000-0000-4000-8000-000000000002','e1d00000-0000-4000-8000-000000000003','e1d00000-0000-4000-8000-000000000004','e1d00000-0000-4000-8000-000000000005','e1d00000-0000-4000-8000-000000000006','e1d00000-0000-4000-8000-000000000007','e1d00000-0000-4000-8000-000000000008','e1d00000-0000-4000-8000-000000000009','e1d00000-0000-4000-8000-000000000010','e1d00000-0000-4000-8000-000000000011','e1d00000-0000-4000-8000-000000000012','e1d00000-0000-4000-8000-000000000013','e1d00000-0000-4000-8000-000000000014','e1d00000-0000-4000-8000-000000000015','e1d00000-0000-4000-8000-000000000016','e1d00000-0000-4000-8000-000000000017','e1d00000-0000-4000-8000-000000000018','e1d00000-0000-4000-8000-000000000019','e1d00000-0000-4000-8000-000000000020','e1d00000-0000-4000-8000-000000000021','e1d00000-0000-4000-8000-000000000022','e1d00000-0000-4000-8000-000000000023','e1d00000-0000-4000-8000-000000000024','e1d00000-0000-4000-8000-000000000025','e1d00000-0000-4000-8000-000000000026','e1d00000-0000-4000-8000-000000000027','e1d00000-0000-4000-8000-000000000028','e1d00000-0000-4000-8000-000000000029','e1d00000-0000-4000-8000-000000000030')
      AND campaign_id = v_campaign_id
      AND person_id IN ('e1b00000-0000-4000-8000-000000000001','e1b00000-0000-4000-8000-000000000002','e1b00000-0000-4000-8000-000000000003','e1b00000-0000-4000-8000-000000000004','e1b00000-0000-4000-8000-000000000005','e1b00000-0000-4000-8000-000000000006','e1b00000-0000-4000-8000-000000000007','e1b00000-0000-4000-8000-000000000008','e1b00000-0000-4000-8000-000000000009','e1b00000-0000-4000-8000-000000000010','e1b00000-0000-4000-8000-000000000011','e1b00000-0000-4000-8000-000000000012','e1b00000-0000-4000-8000-000000000013','e1b00000-0000-4000-8000-000000000014','e1b00000-0000-4000-8000-000000000015','e1b00000-0000-4000-8000-000000000016','e1b00000-0000-4000-8000-000000000017','e1b00000-0000-4000-8000-000000000018','e1b00000-0000-4000-8000-000000000019','e1b00000-0000-4000-8000-000000000020','e1b00000-0000-4000-8000-000000000021','e1b00000-0000-4000-8000-000000000022','e1b00000-0000-4000-8000-000000000023','e1b00000-0000-4000-8000-000000000024','e1b00000-0000-4000-8000-000000000025','e1b00000-0000-4000-8000-000000000026','e1b00000-0000-4000-8000-000000000027','e1b00000-0000-4000-8000-000000000028','e1b00000-0000-4000-8000-000000000029','e1b00000-0000-4000-8000-000000000030')
      AND session_id IN ('e1c00000-0000-4000-8000-000000000001','e1c00000-0000-4000-8000-000000000002','e1c00000-0000-4000-8000-000000000003','e1c00000-0000-4000-8000-000000000004','e1c00000-0000-4000-8000-000000000005','e1c00000-0000-4000-8000-000000000006','e1c00000-0000-4000-8000-000000000007','e1c00000-0000-4000-8000-000000000008','e1c00000-0000-4000-8000-000000000009','e1c00000-0000-4000-8000-000000000010','e1c00000-0000-4000-8000-000000000011','e1c00000-0000-4000-8000-000000000012','e1c00000-0000-4000-8000-000000000013','e1c00000-0000-4000-8000-000000000014','e1c00000-0000-4000-8000-000000000015','e1c00000-0000-4000-8000-000000000016','e1c00000-0000-4000-8000-000000000017','e1c00000-0000-4000-8000-000000000018','e1c00000-0000-4000-8000-000000000019','e1c00000-0000-4000-8000-000000000020','e1c00000-0000-4000-8000-000000000021','e1c00000-0000-4000-8000-000000000022','e1c00000-0000-4000-8000-000000000023','e1c00000-0000-4000-8000-000000000024','e1c00000-0000-4000-8000-000000000025','e1c00000-0000-4000-8000-000000000026','e1c00000-0000-4000-8000-000000000027','e1c00000-0000-4000-8000-000000000028','e1c00000-0000-4000-8000-000000000029','e1c00000-0000-4000-8000-000000000030');

    IF v_count <> 30 THEN
        RAISE EXCEPTION 'DETENCIÓN DE SEGURIDAD: Se esperaban 30 participantes de campaña vinculados, pero se encontraron %.', v_count;
    END IF;

    -- ==========================================================================
    -- 6. INSPECCIÓN INDIVIDUAL Y OBLIGATORIA DEL ESTADO DE LAS 30 SESIONES
    -- ==========================================================================
    -- Los triggers de producción (protect_finalized_session_deletion y
    -- protect_finalized_session_measurement_values) prohíben estrictamente el DELETE
    -- físico si status IN ('completed', 'verified', 'archived').
    -- Si alguna sesión NO está en 'draft', el rollback SE ABORTA EN SU TOTALIDAD.
    SELECT 
        COUNT(*),
        COALESCE(string_agg(id::text || ' [estado: ' || status || ']', ', '), '')
    INTO v_non_draft_count, v_non_draft_details
    FROM public.measurement_sessions
    WHERE id IN ('e1c00000-0000-4000-8000-000000000001','e1c00000-0000-4000-8000-000000000002','e1c00000-0000-4000-8000-000000000003','e1c00000-0000-4000-8000-000000000004','e1c00000-0000-4000-8000-000000000005','e1c00000-0000-4000-8000-000000000006','e1c00000-0000-4000-8000-000000000007','e1c00000-0000-4000-8000-000000000008','e1c00000-0000-4000-8000-000000000009','e1c00000-0000-4000-8000-000000000010','e1c00000-0000-4000-8000-000000000011','e1c00000-0000-4000-8000-000000000012','e1c00000-0000-4000-8000-000000000013','e1c00000-0000-4000-8000-000000000014','e1c00000-0000-4000-8000-000000000015','e1c00000-0000-4000-8000-000000000016','e1c00000-0000-4000-8000-000000000017','e1c00000-0000-4000-8000-000000000018','e1c00000-0000-4000-8000-000000000019','e1c00000-0000-4000-8000-000000000020','e1c00000-0000-4000-8000-000000000021','e1c00000-0000-4000-8000-000000000022','e1c00000-0000-4000-8000-000000000023','e1c00000-0000-4000-8000-000000000024','e1c00000-0000-4000-8000-000000000025','e1c00000-0000-4000-8000-000000000026','e1c00000-0000-4000-8000-000000000027','e1c00000-0000-4000-8000-000000000028','e1c00000-0000-4000-8000-000000000029','e1c00000-0000-4000-8000-000000000030')
      AND status IS DISTINCT FROM 'draft';

    IF v_non_draft_count > 0 THEN
        RAISE EXCEPTION 
            'DETENCIÓN TOTAL DEL ROLLBACK: Se identificaron % sesión(es) que no están en estado "draft": [%]. '
            'Los triggers de integridad de producción impiden eliminar sesiones o valores finalizados. '
            'Para no realizar una reversión parcial ni dejar registros huérfanos o archivados, el rollback '
            'se detiene por completo sin modificar ningún registro. '
            'ALTERNATIVA: Si se requiere retirar estas sesiones, un administrador de base de datos debe '
            'tramitar una desincorporación formal auditada con privilegios de superusuario.',
            v_non_draft_count, v_non_draft_details;
    END IF;

    -- Verificar que existan las 30 sesiones vinculadas al cliente y campaña
    SELECT COUNT(*) INTO v_count
    FROM public.measurement_sessions
    WHERE id IN ('e1c00000-0000-4000-8000-000000000001','e1c00000-0000-4000-8000-000000000002','e1c00000-0000-4000-8000-000000000003','e1c00000-0000-4000-8000-000000000004','e1c00000-0000-4000-8000-000000000005','e1c00000-0000-4000-8000-000000000006','e1c00000-0000-4000-8000-000000000007','e1c00000-0000-4000-8000-000000000008','e1c00000-0000-4000-8000-000000000009','e1c00000-0000-4000-8000-000000000010','e1c00000-0000-4000-8000-000000000011','e1c00000-0000-4000-8000-000000000012','e1c00000-0000-4000-8000-000000000013','e1c00000-0000-4000-8000-000000000014','e1c00000-0000-4000-8000-000000000015','e1c00000-0000-4000-8000-000000000016','e1c00000-0000-4000-8000-000000000017','e1c00000-0000-4000-8000-000000000018','e1c00000-0000-4000-8000-000000000019','e1c00000-0000-4000-8000-000000000020','e1c00000-0000-4000-8000-000000000021','e1c00000-0000-4000-8000-000000000022','e1c00000-0000-4000-8000-000000000023','e1c00000-0000-4000-8000-000000000024','e1c00000-0000-4000-8000-000000000025','e1c00000-0000-4000-8000-000000000026','e1c00000-0000-4000-8000-000000000027','e1c00000-0000-4000-8000-000000000028','e1c00000-0000-4000-8000-000000000029','e1c00000-0000-4000-8000-000000000030')
      AND client_id = v_client_id
      AND campaign_id = v_campaign_id;

    IF v_count <> 30 THEN
        RAISE EXCEPTION 'DETENCIÓN DE SEGURIDAD: Se esperaban 30 sesiones vinculadas, pero se encontraron %.', v_count;
    END IF;

    -- ==========================================================================
    -- 7. VERIFICACIÓN DE LOS 300 VALORES DE MEDICIÓN
    -- ==========================================================================
    SELECT COUNT(*) INTO v_count
    FROM public.measurement_values
    WHERE session_id IN ('e1c00000-0000-4000-8000-000000000001','e1c00000-0000-4000-8000-000000000002','e1c00000-0000-4000-8000-000000000003','e1c00000-0000-4000-8000-000000000004','e1c00000-0000-4000-8000-000000000005','e1c00000-0000-4000-8000-000000000006','e1c00000-0000-4000-8000-000000000007','e1c00000-0000-4000-8000-000000000008','e1c00000-0000-4000-8000-000000000009','e1c00000-0000-4000-8000-000000000010','e1c00000-0000-4000-8000-000000000011','e1c00000-0000-4000-8000-000000000012','e1c00000-0000-4000-8000-000000000013','e1c00000-0000-4000-8000-000000000014','e1c00000-0000-4000-8000-000000000015','e1c00000-0000-4000-8000-000000000016','e1c00000-0000-4000-8000-000000000017','e1c00000-0000-4000-8000-000000000018','e1c00000-0000-4000-8000-000000000019','e1c00000-0000-4000-8000-000000000020','e1c00000-0000-4000-8000-000000000021','e1c00000-0000-4000-8000-000000000022','e1c00000-0000-4000-8000-000000000023','e1c00000-0000-4000-8000-000000000024','e1c00000-0000-4000-8000-000000000025','e1c00000-0000-4000-8000-000000000026','e1c00000-0000-4000-8000-000000000027','e1c00000-0000-4000-8000-000000000028','e1c00000-0000-4000-8000-000000000029','e1c00000-0000-4000-8000-000000000030');

    IF v_count <> 300 THEN
        RAISE EXCEPTION 'DETENCIÓN DE SEGURIDAD: Se esperaban exactamente 300 valores de medidas, pero se encontraron %.', v_count;
    END IF;

    -- ==========================================================================
    -- 8. VERIFICACIÓN DE LAS 45 CREACIONES Y SUS RELACIONES CON LOS ALUMNOS
    -- ==========================================================================
    SELECT COUNT(*) INTO v_count
    FROM public.creations
    WHERE id IN ('e1e00000-0000-4000-8000-000000000001','e1e00000-0000-4000-8000-000000000002','e1e00000-0000-4000-8000-000000000003','e1e00000-0000-4000-8000-000000000004','e1e00000-0000-4000-8000-000000000005','e1e00000-0000-4000-8000-000000000006','e1e00000-0000-4000-8000-000000000007','e1e00000-0000-4000-8000-000000000008','e1e00000-0000-4000-8000-000000000009','e1e00000-0000-4000-8000-000000000010','e1e00000-0000-4000-8000-000000000011','e1e00000-0000-4000-8000-000000000012','e1e00000-0000-4000-8000-000000000013','e1e00000-0000-4000-8000-000000000014','e1e00000-0000-4000-8000-000000000015','e1e00000-0000-4000-8000-000000000016','e1e00000-0000-4000-8000-000000000017','e1e00000-0000-4000-8000-000000000018','e1e00000-0000-4000-8000-000000000019','e1e00000-0000-4000-8000-000000000020','e1e00000-0000-4000-8000-000000000021','e1e00000-0000-4000-8000-000000000022','e1e00000-0000-4000-8000-000000000023','e1e00000-0000-4000-8000-000000000024','e1e00000-0000-4000-8000-000000000025','e1e00000-0000-4000-8000-000000000026','e1e00000-0000-4000-8000-000000000027','e1e00000-0000-4000-8000-000000000028','e1e00000-0000-4000-8000-000000000029','e1e00000-0000-4000-8000-000000000030','e1e00000-0000-4000-8000-000000000031','e1e00000-0000-4000-8000-000000000032','e1e00000-0000-4000-8000-000000000033','e1e00000-0000-4000-8000-000000000034','e1e00000-0000-4000-8000-000000000035','e1e00000-0000-4000-8000-000000000036','e1e00000-0000-4000-8000-000000000037','e1e00000-0000-4000-8000-000000000038','e1e00000-0000-4000-8000-000000000039','e1e00000-0000-4000-8000-000000000040','e1e00000-0000-4000-8000-000000000041','e1e00000-0000-4000-8000-000000000042','e1e00000-0000-4000-8000-000000000043','e1e00000-0000-4000-8000-000000000044','e1e00000-0000-4000-8000-000000000045')
      AND client_id = v_client_id
      AND person_id IN ('e1b00000-0000-4000-8000-000000000001','e1b00000-0000-4000-8000-000000000002','e1b00000-0000-4000-8000-000000000003','e1b00000-0000-4000-8000-000000000004','e1b00000-0000-4000-8000-000000000005','e1b00000-0000-4000-8000-000000000006','e1b00000-0000-4000-8000-000000000007','e1b00000-0000-4000-8000-000000000008','e1b00000-0000-4000-8000-000000000009','e1b00000-0000-4000-8000-000000000010','e1b00000-0000-4000-8000-000000000011','e1b00000-0000-4000-8000-000000000012','e1b00000-0000-4000-8000-000000000013','e1b00000-0000-4000-8000-000000000014','e1b00000-0000-4000-8000-000000000015','e1b00000-0000-4000-8000-000000000016','e1b00000-0000-4000-8000-000000000017','e1b00000-0000-4000-8000-000000000018','e1b00000-0000-4000-8000-000000000019','e1b00000-0000-4000-8000-000000000020','e1b00000-0000-4000-8000-000000000021','e1b00000-0000-4000-8000-000000000022','e1b00000-0000-4000-8000-000000000023','e1b00000-0000-4000-8000-000000000024','e1b00000-0000-4000-8000-000000000025','e1b00000-0000-4000-8000-000000000026','e1b00000-0000-4000-8000-000000000027','e1b00000-0000-4000-8000-000000000028','e1b00000-0000-4000-8000-000000000029','e1b00000-0000-4000-8000-000000000030')
      AND session_id IN ('e1c00000-0000-4000-8000-000000000001','e1c00000-0000-4000-8000-000000000002','e1c00000-0000-4000-8000-000000000003','e1c00000-0000-4000-8000-000000000004','e1c00000-0000-4000-8000-000000000005','e1c00000-0000-4000-8000-000000000006','e1c00000-0000-4000-8000-000000000007','e1c00000-0000-4000-8000-000000000008','e1c00000-0000-4000-8000-000000000009','e1c00000-0000-4000-8000-000000000010','e1c00000-0000-4000-8000-000000000011','e1c00000-0000-4000-8000-000000000012','e1c00000-0000-4000-8000-000000000013','e1c00000-0000-4000-8000-000000000014','e1c00000-0000-4000-8000-000000000015','e1c00000-0000-4000-8000-000000000016','e1c00000-0000-4000-8000-000000000017','e1c00000-0000-4000-8000-000000000018','e1c00000-0000-4000-8000-000000000019','e1c00000-0000-4000-8000-000000000020','e1c00000-0000-4000-8000-000000000021','e1c00000-0000-4000-8000-000000000022','e1c00000-0000-4000-8000-000000000023','e1c00000-0000-4000-8000-000000000024','e1c00000-0000-4000-8000-000000000025','e1c00000-0000-4000-8000-000000000026','e1c00000-0000-4000-8000-000000000027','e1c00000-0000-4000-8000-000000000028','e1c00000-0000-4000-8000-000000000029','e1c00000-0000-4000-8000-000000000030');

    IF v_count <> 45 THEN
        RAISE EXCEPTION 'DETENCIÓN DE SEGURIDAD: Se esperaban 45 creaciones vinculadas a los alumnos del demo, pero se encontraron %.', v_count;
    END IF;

    -- ==========================================================================
    -- 9. VERIFICACIÓN DE INEXISTENCIA DE DEPENDENCIAS EXTERNAS O POSTERIORES
    -- ==========================================================================
    -- Comprobar si alguna de las 45 creaciones o 30 sesiones fue vinculada a
    -- ejecuciones de patrones posteriores (pattern_executions)
    SELECT COUNT(*) INTO v_external_ref_count
    FROM public.pattern_executions
